<template>
    <main class="pm-page">
        <header class="page-header">
            <div><p class="eyebrow">PREDICTIVE MAINTENANCE</p><h1>설비 상태 모니터링</h1><p class="muted">장비별 위험도와 이상 상태를 한눈에 확인합니다. <b v-if="dashboard.collectedAt">시뮬레이션 시각 {{ formatFullDate(dashboard.collectedAt) }}</b></p></div>
            <div class="header-actions"><MaintenanceModeSwitch v-model="selectedMode" @update:model-value="changeMode" /><SimulationAlertControls v-if="selectedMode === 'DEMO'" v-model="telegramAlertsEnabled" :running="autoPlaying" :busy="loading" @update:model-value="handleTelegramAlertToggle" @toggle-simulation="toggleDemo" /><button class="refresh" type="button" :disabled="loading" @click="load">{{ loading ? "조회 중..." : "새로고침" }}</button><button class="dashboard-close" type="button" @click="closeDashboard">닫기</button></div>
        </header>

        <p v-if="error" class="error">{{ error }}</p>
        <p v-if="telegramMessage" class="telegram-result" :class="telegramResultTone">{{ telegramMessage }}</p>
        <section class="control-overview">
            <div class="severity-stack">
                <article class="severity-box critical"><span>위험 장비</span><strong>{{ dashboard.criticalCount }}</strong><small>즉시 점검 필요</small></article>
                <article class="severity-box warning"><span>주의 장비</span><strong>{{ dashboard.warningCount }}</strong><small>상태 확인 필요</small></article>
            </div>
            <article class="overview-card health-overview"><div><p class="overview-label">전체 장비 상태</p><h2>상태 / 건전성</h2></div><div class="fleet-donut" :style="healthDonutStyle"><div><strong>{{ dashboard.totalEquipment }}</strong><small>전체</small></div></div><div class="fleet-legend"><span class="critical"><i></i>위험 <b>{{ dashboard.criticalCount }}</b></span><span class="warning"><i></i>주의 <b>{{ dashboard.warningCount }}</b></span><span class="normal"><i></i>정상 <b>{{ dashboard.normalCount }}</b></span></div></article>
            <article class="overview-card operations-overview"><p class="overview-label">운영 정보</p><h2>설비 현황</h2><dl><div><dt>전체 장비</dt><dd>{{ dashboard.totalEquipment }}</dd></div><div><dt>운영 정상</dt><dd>{{ dashboard.normalCount }}</dd></div><div><dt>확인 필요</dt><dd>{{ dashboard.warningCount + dashboard.criticalCount }}</dd></div><div><dt>현재 시각</dt><dd>{{ formatFullDate(dashboard.collectedAt) }}</dd></div></dl></article>
            <article class="overview-card alert-overview"><div class="overview-title"><div><p class="overview-label">ALERT</p><h2>최근 알림</h2></div><strong>{{ alertHistory.length }}</strong></div><div v-if="alertHistory.length" class="mini-alert-list"><button v-for="item in alertHistory" :key="item.eventKey" type="button" @click="openDetail(item)"><i :class="item.alertTone"></i><span><b>{{ item.equipmentId }}</b><small>{{ item.alertLabel }} · {{ issueSummary(item) }}</small></span><time>{{ formatScore(item.riskScore) }} · {{ formatDate(item.collectedAt) }}</time></button></div><p v-else class="all-clear">최근 발생한 이상 알림이 없습니다.</p></article>
        </section>

        <div class="equipment-section-title"><div><p class="overview-label">EQUIPMENT</p><h2>장비별 모니터링</h2></div><span>이름순 · {{ dashboard.totalEquipment }}대</span></div>

        <section class="equipment-grid">
            <button v-for="item in sortedEquipment" :key="item.equipmentId" class="equipment-card compact" :class="item.riskLevel?.toLowerCase()" type="button" @click="openDetail(item)">
                <strong class="equipment-name">{{ item.equipmentId }}</strong>
                <div class="compact-gauge" :style="gaugeStyle(item)"><div><strong>{{ formatScore(item.riskScore) }}</strong><small>{{ riskLabel(item.riskLevel) }}</small></div></div>
                <div class="compact-meta"><span>{{ item.locationId || "위치 미지정" }} · {{ item.equipmentType || "장비" }}</span><b>{{ issueSummary(item) }}</b></div>
            </button>
            <div v-if="!loading && !sortedEquipment.length" class="empty-card">센서 데이터가 없습니다.</div>
        </section>

        <div v-if="showRiskAlert" class="modal-backdrop risk-alert-backdrop" @click.self="dismissRiskAlert"><section class="risk-alert-modal"><button class="close" type="button" aria-label="닫기" @click="dismissRiskAlert">×</button><p class="eyebrow">EQUIPMENT ALERT</p><h2>이상 장비가 감지되었습니다</h2><p class="alert-description">새로운 점검 알림 {{ popupAlerts.length }}건이 발생했습니다.</p><div class="alert-equipment-list"><button v-for="item in popupAlerts" :key="item.eventKey" type="button" :class="item.alertTone" @click="openAlertDetail(item)"><span><strong>{{ item.equipmentId }}</strong><small>{{ issueSummary(item) }}</small></span><b>{{ item.alertLabel }} · {{ formatScore(item.riskScore) }}</b></button></div><button class="confirm-button" type="button" @click="dismissRiskAlert">확인</button></section></div>

        <div v-if="selected" class="modal-backdrop industrial-backdrop" @click.self="closeDetail"><section class="industrial-detail"><button class="industrial-close" type="button" aria-label="닫기" @click="closeDetail">×</button><header class="industrial-header"><div><p>REMOTE DIAGNOSIS SYSTEM</p><h2>{{ selected.equipmentId }} 설비 진단</h2><span>{{ selected.equipmentType || "장비" }} · {{ selected.locationId || "위치 미지정" }}</span></div><div class="industrial-clock"><strong>{{ formatFullDate(selected.collectedAt) }}</strong><span class="industrial-state" :class="selected.riskLevel?.toLowerCase()">{{ riskLabel(selected.riskLevel) }}</span></div></header><p v-if="detailLoading" class="detail-loading dark">시간별 데이터를 불러오는 중입니다.</p><template v-else><section class="metric-panel"><article v-for="metric in detailMetrics" :key="metric.label" class="metric-card" :class="metric.tone"><h3>{{ metric.label }}</h3><div class="metric-gauge" :style="metricGaugeStyle(metric)"><div><strong>{{ metric.value }}</strong><small>{{ metric.unit }}</small></div></div><span>{{ metric.caption }}</span></article></section><section class="industrial-lower"><article class="dark-panel trend-panel"><div class="dark-panel-title"><h3>시간별 위험도 추이</h3><span>최근 {{ detailHistory.length }}개 수집 시점</span></div><div ref="historyChart" class="history-chart dark-chart"></div></article><article class="dark-panel log-panel"><div class="dark-panel-title"><h3>설비 상태 로그</h3><span>{{ issueSummary(selected) }}</span></div><div class="history-log dark-log"><div v-for="point in reversedHistory" :key="point.collectedAt" class="history-log-row" :class="point.riskLevel?.toLowerCase()"><time>{{ formatFullDate(point.collectedAt) }}</time><span class="history-state">{{ riskLabel(point.riskLevel) }}</span><strong>{{ formatScore(point.riskScore) }}</strong><span>{{ issueSummary(point) }}</span></div><p v-if="!detailHistory.length" class="empty">조회된 시간별 기록이 없습니다.</p></div></article></section></template></section></div>
    </main>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from "vue"
import { useRoute, useRouter } from "vue-router"
import { getEquipmentAlerts, getEquipmentHistory, getPredictiveMaintenanceDashboardByMode, sendTelegramAlertMessages, startPredictiveMaintenanceDemo, stopPredictiveMaintenanceDemo } from "../api/predictiveMaintenanceApi"
import SimulationAlertControls from "../components/SimulationAlertControls.vue"
import MaintenanceModeSwitch from "../components/MaintenanceModeSwitch.vue"

const loading = ref(false), error = ref(""), selected = ref(null), showRiskAlert = ref(false)
const telegramAlertsEnabled = ref(false), telegramMessage = ref(""), telegramResultTone = ref("success")
const detailLoading = ref(false), detailHistory = ref([]), historyChart = ref(null)
const autoPlaying = ref(false)
const resumeAfterAlert = ref(false), hasMoreData = ref(true)
const alertHistory = ref([]), popupAlerts = ref([])
const demoRunId = ref(null)
const selectedMode = ref("LIVE")
const route = useRoute()
const router = useRouter()
let autoTimer = null
const DEMO_START_TIME = "2026-01-23T10:00:00"
const dashboard = reactive({ collectedAt: null, totalEquipment: 0, normalCount: 0, warningCount: 0, criticalCount: 0, equipment: [] })
const sortedEquipment = computed(() => [...(dashboard.equipment || [])].sort((a, b) => String(a.equipmentId || "").localeCompare(String(b.equipmentId || ""), "ko", { numeric: true })))
const abnormalEquipment = computed(() => sortedEquipment.value.filter(item => item.riskLevel === "WARNING" || item.riskLevel === "CRITICAL"))
const reversedHistory = computed(() => [...detailHistory.value].reverse())
const healthDonutStyle = computed(() => { const total = Math.max(1, dashboard.totalEquipment); const criticalEnd = dashboard.criticalCount / total * 360; const warningEnd = criticalEnd + dashboard.warningCount / total * 360; return { background: `conic-gradient(#e11d3f 0 ${criticalEnd}deg, #f59e0b ${criticalEnd}deg ${warningEnd}deg, #22a667 ${warningEnd}deg 360deg)` } })
const detailMetrics = computed(() => selected.value ? [
    { label: "지난 경고", value: selected.value.warningEventCount || 0, unit: "건", percent: Math.min(100, (selected.value.warningEventCount || 0) * 10), tone: (selected.value.warningEventCount || 0) > 0 ? "warning" : "normal", caption: selectedMode.value === "DEMO" ? "현재 시연 회차" : "운영 이력" },
    { label: "위험도", value: formatScore(selected.value.riskScore), unit: "/ 100", percent: selected.value.riskScore || 0, tone: selected.value.riskLevel?.toLowerCase(), caption: riskLabel(selected.value.riskLevel) },
    { label: "통신 성공률", value: formatNumber(selected.value.successRate), unit: "%", percent: selected.value.successRate || 0, tone: selected.value.successRate < 95 ? "warning" : "normal", caption: selected.value.successRate < 95 ? "성공률 저하" : "정상" },
    { label: "응답시간", value: formatNumber(selected.value.responseTimeMs), unit: "ms", percent: Math.min(100, (selected.value.responseTimeMs || 0) / 5), tone: selected.value.responseTimeMs > 200 ? "critical" : "cyan", caption: selected.value.responseTimeMs > 200 ? "응답 지연" : "정상" },
    { label: "패킷 손실", value: formatNumber(selected.value.packetLossRate), unit: "%", percent: Math.min(100, (selected.value.packetLossRate || 0) * 10), tone: selected.value.packetLossRate > 1 ? "warning" : "normal", caption: selected.value.packetLossRate > 1 ? "손실 증가" : "정상" },
    { label: "신호 세기", value: formatNumber(selected.value.signalStrengthDbm), unit: "dBm", percent: Math.min(100, Math.max(0, ((selected.value.signalStrengthDbm || -100) + 100) / 70 * 100)), tone: selected.value.signalStrengthDbm < -70 ? "critical" : "cyan", caption: selected.value.signalStrengthDbm < -70 ? "신호 약함" : "정상" },
    { label: "장비 온도", value: formatNumber(selected.value.temperatureC), unit: "°C", percent: Math.min(100, (selected.value.temperatureC || 0) / 60 * 100), tone: selected.value.temperatureC > 45 ? "warning" : "normal", caption: selected.value.temperatureC > 45 ? "온도 상승" : "정상" }
] : [])
async function load() { loading.value = true; error.value = ""; try { const response = await getPredictiveMaintenanceDashboardByMode(selectedMode.value); Object.assign(dashboard, response); demoRunId.value = response.demoRunId || null; telegramAlertsEnabled.value = selectedMode.value === "DEMO" && Boolean(response.telegramEnabled || telegramAlertsEnabled.value); if (selectedMode.value === "DEMO" && response.simulationRunning) startAuto(); else stopAuto() } catch (e) { error.value = e.response?.data?.message || "대시보드 데이터를 불러오지 못했습니다." } finally { loading.value = false } }
async function initializePage() {
    const equipmentId = Array.isArray(route.query.equipmentId) ? route.query.equipmentId[0] : route.query.equipmentId
    selectedMode.value = String(Array.isArray(route.query.mode) ? route.query.mode[0] : route.query.mode || "LIVE").toUpperCase()
    if (!equipmentId) { await load(); return }

    loading.value = true; error.value = ""; showRiskAlert.value = false; popupAlerts.value = []
    try {
        Object.assign(dashboard, await getPredictiveMaintenanceDashboardByMode(selectedMode.value))
        demoRunId.value = dashboard.demoRunId || route.query.demoRunId || null
        const target = dashboard.equipment?.find(item => String(item.equipmentId) === String(equipmentId))
        if (!target) { error.value = `${equipmentId} 장비를 현재 수집 시점에서 찾지 못했습니다.`; return }
        target.warningEventCount = Number(route.query.warningEventCount || 0)
        await openDetail(target)
    } catch (e) { error.value = e.response?.data?.message || "선택한 장비 정보를 불러오지 못했습니다." }
    finally { loading.value = false }
}
async function advance(showAlert = true) { if (!dashboard.collectedAt) return false; const previousStates = new Map(dashboard.equipment.map(item => [item.equipmentId, { riskScore: item.riskScore, riskLevel: item.riskLevel }])); loading.value = true; error.value = ""; try { Object.assign(dashboard, await getNextPredictiveMaintenanceDashboard(dashboard.collectedAt)); await syncOpenDetail(); const newAlerts = recordAlerts(previousStates); if (showAlert && newAlerts.length) { popupAlerts.value = newAlerts; resumeAfterAlert.value = autoPlaying.value; showRiskAlert.value = true; stopAuto(false); sendPopupAlertsToTelegram(newAlerts) } return true } catch (e) { hasMoreData.value = e.response?.status !== 404; error.value = e.response?.status === 404 ? "마지막 데이터입니다." : (e.response?.data?.message || "다음 데이터를 불러오지 못했습니다."); return false } finally { loading.value = false } }
function stopAuto(clearResume = true) { autoPlaying.value = false; if (clearResume) resumeAfterAlert.value = false; if (autoTimer) clearTimeout(autoTimer); autoTimer = null }
async function autoStep() { if (!autoPlaying.value) return; const previousStates = new Map(dashboard.equipment.map(item => [item.equipmentId, { riskScore: item.riskScore, riskLevel: item.riskLevel }])); try { const response = await getPredictiveMaintenanceDashboardByMode("DEMO"); Object.assign(dashboard, response); demoRunId.value = response.demoRunId; await syncOpenDetail(); const newAlerts = recordAlerts(previousStates); if (newAlerts.length) { popupAlerts.value = newAlerts; showRiskAlert.value = true; sendPopupAlertsToTelegram(newAlerts) } if (!response.simulationRunning) { stopAuto(); return } } catch (e) { error.value = e.response?.data?.message || "시연 데이터를 불러오지 못했습니다." } if (autoPlaying.value) autoTimer = setTimeout(autoStep, 500) }
function startAuto() { if (!hasMoreData.value || autoPlaying.value) return; autoPlaying.value = true; autoTimer = setTimeout(autoStep, 500) }
function toggleAuto() { if (autoPlaying.value) { stopAuto(); return } showRiskAlert.value = false; resumeAfterAlert.value = false; startAuto() }
function dismissRiskAlert() { showRiskAlert.value = false; if (resumeAfterAlert.value) { resumeAfterAlert.value = false; startAuto() } }
async function startDemo() { stopAuto(); showRiskAlert.value = false; alertHistory.value = []; popupAlerts.value = []; loading.value = true; error.value = ""; try { const status = await startPredictiveMaintenanceDemo(telegramAlertsEnabled.value); demoRunId.value = status.demoRunId; selectedMode.value = "DEMO"; Object.assign(dashboard, await getPredictiveMaintenanceDashboardByMode("DEMO")); startAuto() } catch (e) { error.value = e.response?.data?.message || "시연을 시작하지 못했습니다." } finally { loading.value = false } }
async function toggleDemo() { if (!autoPlaying.value) { await startDemo(); return } loading.value = true; try { await stopPredictiveMaintenanceDemo(); stopAuto(); Object.assign(dashboard, await getPredictiveMaintenanceDashboardByMode("DEMO")) } catch (e) { error.value = e.response?.data?.message || "시연을 정지하지 못했습니다." } finally { loading.value = false } }
async function changeMode(mode) { selectedMode.value = mode; stopAuto(); selected.value = null; showRiskAlert.value = false; await load() }
function alertPolicy(item) { const score = Number(item.riskScore || 0); if (item.riskLevel === "CRITICAL" || score >= 95) return { rank: 3, label: "긴급정비", tone: "critical" }; if (score >= 80) return { rank: 2, label: "긴급점검", tone: "critical" }; if (score >= 50) return { rank: 1, label: "주의", tone: "warning" }; return { rank: 0, label: "정상", tone: "normal" } }
function recordAlerts(previousStates) { const events = sortedEquipment.value.flatMap(item => { const currentPolicy = alertPolicy(item); const previous = previousStates.get(item.equipmentId); const previousPolicy = previous ? alertPolicy(previous) : { rank: 0 }; if (currentPolicy.rank <= previousPolicy.rank) return []; const eventKey = `${item.equipmentId}-${item.collectedAt}-${currentPolicy.rank}`; return [{ ...item, alertRank: currentPolicy.rank, alertLabel: currentPolicy.label, alertTone: currentPolicy.tone, eventKey: demoRunId.value ? `demo-${demoRunId.value}-${eventKey}` : eventKey }] }); if (events.length) alertHistory.value = [...events.slice().reverse(), ...alertHistory.value].slice(0, 10); return events }
function createDemoRunId() { return globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}` }
async function handleTelegramAlertToggle() { telegramMessage.value = ""; if (telegramAlertsEnabled.value && showRiskAlert.value && popupAlerts.value.length) await sendPopupAlertsToTelegram(popupAlerts.value) }
async function sendPopupAlertsToTelegram(alerts) { if (!telegramAlertsEnabled.value) return; const payload = alerts.map(item => ({ eventKey: item.eventKey, equipmentId: item.equipmentId, locationId: item.locationId, equipmentType: item.equipmentType, collectedAt: item.collectedAt, riskScore: Number(item.riskScore || 0), alertLevel: String(item.alertTone || "warning").toUpperCase(), alertLabel: item.alertLabel, issueSummary: issueSummary(item) })); try { const result = await sendTelegramAlertMessages(payload); if (result.failedCount > 0) { telegramResultTone.value = "error"; telegramMessage.value = `텔레그램 알림 ${result.failedCount}건 발송에 실패했습니다. 발송 이력을 확인해주세요.` } else if (result.successCount > 0) { telegramResultTone.value = "success"; telegramMessage.value = `팝업 알림 ${result.successCount}건을 텔레그램으로 함께 발송했습니다.` } else if (result.skippedCount > 0) { telegramResultTone.value = "success"; telegramMessage.value = `이미 처리된 텔레그램 알림 ${result.skippedCount}건은 중복 발송하지 않았습니다.` } } catch (e) { telegramResultTone.value = "error"; telegramMessage.value = e.response?.data?.message || "팝업은 표시했지만 텔레그램 알림 요청에 실패했습니다." } }
function closeDashboard() { stopAuto(); window.close(); setTimeout(() => { if (!window.closed) router.push({ name: "admin-dashboard" }) }, 100) }
async function openDetail(item) { selected.value = item; detailLoading.value = true; detailHistory.value = []; try { const [history, alerts] = await Promise.all([getEquipmentHistory(item.equipmentId, item.collectedAt || dashboard.collectedAt, 24, selectedMode.value), getEquipmentAlerts(item.equipmentId, selectedMode.value, demoRunId.value)]); detailHistory.value = history; selected.value = { ...item, warningEventCount: alerts.length }; await nextTick(); await renderHistoryChart() } catch (e) { error.value = e.response?.data?.message || "장비 시간별 기록을 불러오지 못했습니다." } finally { detailLoading.value = false; await nextTick(); if (detailHistory.value.length) await renderHistoryChart() } }
async function syncOpenDetail() { if (!selected.value) return; const current = dashboard.equipment?.find(item => item.equipmentId === selected.value.equipmentId); if (!current) return; selected.value = current; const history = detailHistory.value.filter(point => point.collectedAt !== current.collectedAt); history.push(current); detailHistory.value = history.sort((left, right) => String(left.collectedAt).localeCompare(String(right.collectedAt))).slice(-24); await nextTick(); await renderHistoryChart() }
function openAlertDetail(item) { showRiskAlert.value = false; openDetail(item) }
function closeDetail() { selected.value = null; detailHistory.value = []; if (resumeAfterAlert.value) { resumeAfterAlert.value = false; startAuto() } }
async function renderHistoryChart() { if (!historyChart.value || !detailHistory.value.length) return; const module = await import("plotly.js-dist-min"); const Plotly = module.default || module; const points = detailHistory.value; await Plotly.react(historyChart.value, [{ x: points.map(point => point.collectedAt), y: points.map(point => point.riskScore || 0), type: "scatter", mode: "lines+markers", line: { color: "#2563eb", width: 3, shape: "spline" }, marker: { size: 8, color: points.map(point => color(point.riskLevel)) }, fill: "tozeroy", fillcolor: "rgba(37,99,235,.08)", hovertemplate: "%{x}<br>위험도 %{y:.1f}<extra></extra>" }], { margin: { t: 10, r: 16, b: 44, l: 42 }, yaxis: { range: [0, 100], title: "위험도", color: "#64748b", gridcolor: "#e5eaf0" }, xaxis: { type: "date", color: "#64748b", gridcolor: "#eef2f6" }, font: { color: "#334155" }, paper_bgcolor: "transparent", plot_bgcolor: "transparent" }, { responsive: true, displayModeBar: false }) }
function riskLabel(level) { return ({ NORMAL: "정상", WARNING: "주의", CRITICAL: "위험" })[level] || "미확인" }
function color(level) { return level === "CRITICAL" ? "#d9485f" : level === "WARNING" ? "#d48a2d" : "#2e9b69" }
function gaugeStyle(item) { const score = Math.min(100, Math.max(0, item.riskScore || 0)); return { background: `conic-gradient(${color(item.riskLevel)} ${score * 3.6}deg, #e8edf3 0deg)` } }
function formatScore(score) { return Number(score || 0).toFixed(1) }
function formatNumber(value) { return value == null ? "-" : Number(value).toFixed(1) }
function metricGaugeStyle(metric) { const toneColor = ({ critical: "#f02643", warning: "#f2a800", normal: "#12c43b", cyan: "#00cedb" })[metric.tone] || "#00cedb"; return { background: `conic-gradient(${toneColor} ${Math.max(0, Math.min(100, metric.percent)) * 3.6}deg, #555a62 0deg)` } }
function formatDate(value) { return value ? new Date(value).toLocaleString("ko-KR", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }) : "-" }
function formatFullDate(value) { return value ? new Date(value).toLocaleString("ko-KR", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }) : "-" }
function issues(item) { const result = []; if (item.successRate != null && item.successRate < 95) result.push({ label: "성공률 저하", value: `${item.successRate}%` }); if (item.responseTimeMs != null && item.responseTimeMs > 200) result.push({ label: "응답시간 높음", value: `${item.responseTimeMs} ms` }); if (item.packetLossRate != null && item.packetLossRate > 1) result.push({ label: "패킷 손실 증가", value: `${item.packetLossRate}%` }); if (item.signalStrengthDbm != null && item.signalStrengthDbm < -70) result.push({ label: "신호 세기 약함", value: `${item.signalStrengthDbm} dBm` }); return result }
function issueSummary(item) { const list = issues(item); return list.length ? list[0].label : "이상 없음" }
onMounted(initializePage)
onBeforeUnmount(stopAuto)
